    /// Thread safety: It is safe to call this function from any thread, as long as the palette is not modified.
    /// </para>
    /// <para>This function is available since SDL 3.2.0.</para>
    /// <para>
    /// See also: <c>SDL_GetPixelFormatDetails</c>, <c>SDL_GetRGB</c>, <c>SDL_MapRGB</c>, <c>SDL_MapRGBA</c>.
    /// </para>
    /// </remarks>
    /// <param name="pixelvalue">a pixel value.</param>
    /// <param name="format">a pointer to SDL_PixelFormatDetails describing the pixel format.</param>
    /// <param name="palette">an optional palette for indexed formats, may be NULL.</param>
    /// <param name="r">a pointer filled in with the red component, may be NULL.</param>
    /// <param name="g">a pointer filled in with the green component, may be NULL.</param>
    /// <param name="b">a pointer filled in with the blue component, may be NULL.</param>
    /// <param name="a">a pointer filled in with the alpha component, may be NULL.</param>
    public static void GetRGBA(uint pixelvalue, in PixelFormatDetails format, in Palette palette, out byte r, out byte g, out byte b, out byte a)
    {
        r = default;
        g = default;
        b = default;
        a = default;
        fixed (PixelFormatDetails* formatPtr = &format)
        fixed (Palette* palettePtr = &palette)
        fixed (byte* rPtr = &r)
        fixed (byte* gPtr = &g)
        fixed (byte* bPtr = &b)
        fixed (byte* aPtr = &a)
        {
            GetRGBA(pixelvalue, formatPtr, palettePtr, rPtr, gPtr, bPtr, aPtr);
        }
    }
}
